7. Patients with significantly lower heart, liver, lung, kidney and bone marrow function.
8. Severe, uncontrolled medical conditions and infections.
9. At the same time using other test drugs or in other clinical trials.
10. Refusal or inability to sign informed consent to participate in the trial.
11. Other treatment contraindications.
12. Emotional disturbance or mental illness, no civil capacity or limited capacity for civil conduct.
13. Hepatitis B surface antigen (HBsAg) positive and HBVDNA ≥1000cps/ml.
14. Patients with positive HCV antibody test results can only be included in the study when the polymerase chain reaction of HCV RNA is negative.","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"locations":[{"facility":"Sun Yat-sen University Cancer Center","city":"Guangzhou","state":"Guangdong","zip":"510060","country":"China","geoPoint":{"lat":23.11667,"lon":113.25}}]}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-11-24"},"interventionBrowseModule":{"meshes":[{"id":"C000632826","term":"sintilimab"}]}},"hasResults":false},
{"protocolSection":{"identificationModule":{"nctId":"NCT05096221","orgStudyIdInfo":{"id":"SRP-9001-301"},"secondaryIdInfos":[{"id":"2019-003374-91","type":"EUDRACT_NUMBER"}],"organization":{"fullName":"Sarepta Therapeutics, Inc.","class":"INDUSTRY"},"briefTitle":"A Gene Transfer Therapy Study to Evaluate the Safety and Efficacy of Delandistrogene Moxeparvovec (SRP-9001) in Participants With Duchenne Muscular Dystrophy (DMD)","officialTitle":"A Phase 3 Multinational, Randomized, Double-Blind, Placebo-Controlled Systemic Gene Delivery Study to Evaluate the Safety and Efficacy of SRP-9001 in Subjects With Duchenne Muscular Dystrophy (EMBARK)","acronym":"EMBARK"},"statusModule":{"statusVerifiedDate":"2025-06","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2021-10-27","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2023-10-04","type":"ACTUAL"},"completionDateStruct":{"date":"2024-10-25","type":"ACTUAL"},"studyFirstSubmitDate":"2021-10-14","studyFirstSubmitQcDate":"2021-10-14","studyFirstPostDateStruct":{"date":"2021-10-27","type":"ACTUAL"},"resultsFirstSubmitDate":"2024-10-04","resultsFirstSubmitQcDate":"2024-11-22","resultsFirstPostDateStruct":{"date":"2024-12-10","type":"ACTUAL"},"lastUpdateSubmitDate":"2025-06-18","lastUpdatePostDateStruct":{"date":"2025-07-08","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Sarepta Therapeutics, Inc.","class":"INDUSTRY"},"collaborators":[{"name":"Hoffmann-La Roche","class":"INDUSTRY"}]},"oversightModule":{"oversightHasDmc":true,"isFdaRegulatedDrug":true,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"The study will evaluate the safety and efficacy of gene transfer therapy in boys with DMD. It is a randomized, double-blind, placebo-controlled study. The participants who are randomized to the placebo arm will have an opportunity for treatment with gene transfer therapy at the beginning of the second year."},"conditionsModule":{"conditions":["Duchenne Muscular Dystrophy"],"keywords":["Muscular Dystrophies","Duchenne Muscular Dystrophy","DMD","North Star Ambulatory Assessment (NSAA)","Ambulatory","Pediatric","Gene-Delivery"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE3"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"QUADRUPLE","whoMasked":["PARTICIPANT","CARE_PROVIDER","INVESTIGATOR","OUTCOMES_ASSESSOR"]}},"enrollmentInfo":{"count":126,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Delandistrogene Moxeparvovec followed by Placebo","type":"EXPERIMENTAL","description":"Participants will receive single intravenous (IV) infusion of delandistrogene moxeparvovec on Day 1. Then, participants will receive a single IV infusion of matching placebo at Year 2.","interventionNames":["Genetic: delandistrogene moxeparvovec","Genetic: placebo"]},{"label":"Placebo followed by Delandistrogene Moxeparvovec","type":"PLACEBO_COMPARATOR","description":"Participants will receive matching placebo IV infusion on Day 1. Then, participants will have the opportunity to receive a single IV infusion of delandistrogene moxeparvovec at Year 2.","interventionNames":["Genetic: delandistrogene moxeparvovec","Genetic: placebo"]}],"interventions":[{"type":"GENETIC","name":"delandistrogene moxeparvovec","description":"Single IV infusion of delandistrogene moxeparvovec.","armGroupLabels":["Delandistrogene Moxeparvovec followed by Placebo","Placebo followed by Delandistrogene Moxeparvovec"],"otherNames":["SRP-9001","delandistrogene moxeparvovec-rokl","ELEVIDYS"]},{"type":"GENETIC","name":"placebo","description":"Single IV infusion of matching placebo.","armGroupLabels":["Delandistrogene Moxeparvovec followed by Placebo","Placebo followed by Delandistrogene Moxeparvovec"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Part 1: Change From Baseline in North Star Ambulatory Assessment (NSAA) Total Score at Week 52","description":"The NSAA is a healthcare provider administered scale that rates performance of various motor abilities in ambulant children with Duchenne Muscular Dystrophy and is used to monitor disease progression and treatment effects. During assessment, participants are asked to perform 17 different functional activities that are graded as: 2 - "Normal" - no obvious modification of activity; 1 - Modified method but achieves goal independent of assistance; 0 - Unable to achieve independently. The NSAA total score is defined as the sum of all 17 items, ranging from 0 (worst) to 34 (best). The response vector consists of the change from baseline in NSAA total score at the post-baseline visit. The model includes the covariates of treatment group, visit, treatment group by visit interaction, age group, baseline NSAA total score, and baseline NSAA total score by visit interaction. All covariates are fixed effects in this analysis. An increase in score indicates an improvement in motor function.","timeFrame":"Baseline, Week 52 (Part 1)"}],"secondaryOutcomes":[{"measure":"Part 1: Quantity of Delandistrogene Moxeparvovec Dystrophin Protein Expression at Week 12 as Measured by Western Blot Adjusted by Muscle Content","description":"Quantity of delandistrogene moxeparvovec dystrophin protein levels (in muscle biopsy samples) were determined by Western blot at Part 1, Week 12. For this endpoint, 2 blocks of tissues were analyzed by Western blot, each with 2 technical replicates to determine the delandistrogene moxeparvovec dystrophin protein level (percent control). The block average value from 2 technical replicates was computed. The overall average was calculated as the mean of the block average values. The overall average values were used for the analysis. Dystrophin protein was measured and then adjusted based on the percentage of muscle content in the biopsy sample. An increase in protein expression indicates production of the delandistrogene moxeparvovec dystrophin protein.","timeFrame":"Week 12"},{"measure":"Part 1: Change From Baseline in Time to Rise From the Floor at Week 52","description":"The time to rise from the floor test quantifies the time required for the participant to stand in an upright position with arms by sides, starting from the supine position with arms by sides. Data are presented for the change from baseline to Week 52 in the time taken (in seconds) to rise from the floor.","timeFrame":"Baseline, Week 52 (Part 1)"},{"measure":"Part 1: Change From Baseline in Time to Complete 10 Meter Walk/Run (10MWR) at Week 52","description":"The timed 10MWR quantifies the time required for the participant to run or walk 10 meters (on a straight walkway) from a standing position. Data are presented for change from baseline to Week 52 in the time (in seconds) taken to complete the 10MWR.","timeFrame":"Baseline, Week 52 (Part 1)"},{"measure":"Part 1: Change From Baseline in Time to Complete 100 Meter Walk/Run (100MWR) at Week 52","description":"The timed 100MWR quantifies the time required for the participant to run or walk 100 meters (on a straight walkway) from a standing position. Data are presented for change from baseline to Week 52 in the time (in seconds) taken to complete the 100MWR.","timeFrame":"Baseline, Week 52 (Part 1)"},{"measure":"Part 1: Change From Baseline in the Timed Stair Ascend 4 Steps Test at Week 52","description":"The timed stair ascend 4 steps test quantifies the time required for the participant to ascend 4 standard steps (each step was 6 inches in height). Data presented is the change from baseline to Week 52 in the time (in seconds) to ascend 4 steps.","timeFrame":"Baseline, Week 52 (Part 1)"},{"measure":"Part 1: Change From Baseline in Stride Velocity 95th Centile (SV95C) at Week 52","description":"Each participant was provided with wearable devices to collect data on stride velocity. Participants wore a device on each ankle. SV95C data was derived based on stride velocity. Data are presented for change from baseline to Week 52 in SV95C.","timeFrame":"Baseline, Week 52 (Part 1)"},{"measure":"Part 1: Change From Baseline in Patient-Reported Outcomes Measurement Information System (PROMIS) Score in Mobility to Week 52","description":"PROMIS is a family of instruments developed and validated to assess health-related quality of life, including mobility. Mobility function scores ranged from 1 (worst mobility function) to 5 (best mobility function), where higher scores indicate a better clinical outcome.","timeFrame":"Baseline, Week 52 (Part 1)"},{"measure":"Part 1: Change From Baseline in PROMIS Score in Upper Extremity Function to Week 52","description":"PROMIS is a family of instruments developed and validated to assess health-related quality of life, including upper extremity function. Upper extremity function scores ranged from 1 (not able to do so \[worst upper extremity function\]) to 5 (no trouble \[best upper extremity function\]), where higher scores indicate a better clinical outcome.","timeFrame":"Baseline, Week 52 (Part 1)"},{"measure":"Part 1: Number of Skills Gained or Improved at Week 52 as Measured by the NSAA","description":"The NSAA is a clinician-administered scale that rates performance on various functional activities. As measured by the NSAA, data was collected for the number of skills gained (the average item score was 0 at Baseline and \> 0 at Part 1 Week 52) or improved (the average item score at Baseline was \> 0 but less than the average item score at Part 1 Week 52). As pre-specified, data are presented for the combined number of skills gained or improved at Week 52.","timeFrame":"Week 52 (Part 1)"},{"measure":"Parts 1 and 2: Number of Participants With Treatment Emergent Adverse Events (TEAEs) and Serious Adverse Events (SAEs)","description":"TEAEs were defined as an adverse event (AE) that emerged during treatment, having been absent pre-treatment, or worsened relative to the pretreatment state. SAEs were defined as any adverse event that resulted in death, was life threatening, required or prolonged inpatient hospitalization, persistent or significant disability/incapacity, congenital anomaly/birth defect, or was an important medical event. A summary of all Serious Adverse Events and Other Adverse Events (nonserious) regardless of causality is located in the 'Reported Adverse Events' Section.","timeFrame":"Up to 104 weeks"},{"measure":"Parts 1 and 2: Number of Participants With Adverse Events of Special Interest (AESI)","description":"AESIs were defined as adverse events (AEs) of special interest, based on pre-specified criteria and pertain to categories labeled hepatotoxicity, immune-mediated myositis, thrombotic microangiopathy (TMA), hypersensitivity, thrombocytopenia, rhabdomyolysis, and troponin I elevations. The data represent the number of participants who experienced an event within the specified AESI category as observed by the principal investigator (PI), after adjudication. Per prespecified analysis, AESI data were only collected based on the specified AESI categories. A Summary of all SAEs and nonserious AEs ("Other"), regardless of causality and regardless of the AESI category, is located in the "Reported Adverse Events" section.","timeFrame":"Up to 104 weeks"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Is ambulatory and from 4 to under 8 years of age at time of randomization.
* Definitive diagnosis of DMD based on documented clinical findings and prior genetic testing.
* Ability to cooperate with motor assessment testing.
* Stable daily dose of oral corticosteroids for at least 12 weeks prior to Screening, and the dose is expected to remain constant throughout the study (except for modifications to accommodate changes in weight).
* rAAVrh74 antibody titers are not elevated as per protocol-specified requirements.
* A pathogenic frameshift mutation or premature stop codon contained between exons 18 and 79 (inclusive), with the exception of mutation fully contained within exon 45.

Exclusion Criteria:

* Exposure to gene therapy, investigational medication, or any treatment designed to increase dystrophin expression within protocol specified time limits.
* Abnormality in protocol-specified diagnostic evaluations or laboratory tests.
* Presence of any other clinically significant illness, medical condition, or requirement for chronic drug treatment that in the opinion of the Investigator creates unnecessary risk for gene transfer.

Other inclusion or exclusion criteria could apply.","healthyVolunteers":false,"sex":"MALE","minimumAge":"4 Years","maximumAge":"7 Years","stdAges":["CHILD"]},"contactsLocationsModule":{"overallOfficials":[{"name":"Medical Director","affiliation":"Sarepta Therapeutics, Inc.","role":"STUDY_DIRECTOR"}],"locations":[{"facility":"Arkansas Children's","city":"Little Rock","state":"Arkansas","zip":"72202","country":"United States","geoPoint":{"lat":34.74648,"lon":-92.28959}},{"facility":"UC San Diego Altman Clinical and Translational Research Institute","city":"La Jolla","state":"California","zip":"92037","country":"United States","geoPoint":{"lat":32.84727,"lon":-117.2742}},{"facility":"UCLA Medical Center","city":"Los Angeles","state":"California","zip":"90095","country":"United States","geoPoint":{"lat":34.05223,"lon":-118.24368}},{"facility":"Lucile Packard Children's Hospital at Stanford","city":"Palo Alto","state":"California","zip":"94304","country":"United States","geoPoint":{"lat":37.44188,"lon":-122.14302}},{"facility":"University of California, Davis","city":"Sacramento","state":"California","zip":"95817","country":"United States","geoPoint":{"lat":38.58157,"lon":-121.4944}},{"facility":"Children's Hospital Colorado","city":"Aurora","state":"Colorado","zip":"80045","country":"United States","geoPoint":{"lat":39.72943,"lon":-104.83192}},{"facility":"University of Florida","city":"Gainesville","state":"Florida","zip":"32608","country":"United States","geoPoint":{"lat":29.65163,"lon":-82.32483}},{"facility":"Lurie Children's Hospital of Chicago","city":"Chicago","state":"Illinois","zip":"60611","country":"United States","geoPoint":{"lat":41.85003,"lon":-87.65005}},{"facility":"University of Iowa Stead Family Children's Hospital","city":"Iowa City","state":"Iowa","zip":"52242","country":"United States","geoPoint":{"lat":41.66113,"lon":-91.53017}},{"facility":"The Johns Hopkins Hospital","city":"Baltimore","state":"Maryland","zip":"21287","country":"United States","g