dvanced"],"keywords":["nal-IRI","5-Fluorouracil"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE2"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":100,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Nal-IRI + 5-FU + leucovorin (Arm A)","type":"EXPERIMENTAL","description":"nal-IRI \[Irinotecan liposome\] (80 mg/m2 as a 1.5 hour infusion), 5-FU \[5-Fluorouracil\] (2400 mg/m2 as 46 hour infusion) and leucovorin (400 mg/m2 as 0.5 hour infusion) (q2w)","interventionNames":["Drug: nal-IRI","Drug: 5-FU","Drug: leucovorin"]},{"label":"5-FU + leucovorin (Arm B)","type":"OTHER","description":"Control intervention/standard arm: 5-FU (2400 mg/m2 as 46 hour infusion) and leucovorin (400 mg/m2 as 0.5 hour infusion) (q2w)","interventionNames":["Drug: 5-FU","Drug: leucovorin"]}],"interventions":[{"type":"DRUG","name":"nal-IRI","description":"nal-IRI \[Irinotecan liposome\] (80 mg/m2 as a 1.5 hour infusion)","armGroupLabels":["Nal-IRI + 5-FU + leucovorin (Arm A)"]},{"type":"DRUG","name":"5-FU","description":"5-FU \[5-Fluorouracil\] (2400 mg/m2 as 46 hour infusion)","armGroupLabels":["5-FU + leucovorin (Arm B)","Nal-IRI + 5-FU + leucovorin (Arm A)"]},{"type":"DRUG","name":"leucovorin","description":"leucovorin (400 mg/m2 as 0.5 hour infusion)","armGroupLabels":["5-FU + leucovorin (Arm B)","Nal-IRI + 5-FU + leucovorin (Arm A)"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"progression-free survival","timeFrame":"approx 42 months"}],"secondaryOutcomes":[{"measure":"Overall survival","timeFrame":"approx 42 months"},{"measure":"Objective tumor response rate (ORR) according to RECIST 1.1","description":"Response Evaluation Criteria in Solid Tumors (RECIST 1.1.)","timeFrame":"approx 42 months"},{"measure":"Toxicity/Safety","description":"according to Common Terminology Criteria for Adverse Events","timeFrame":"approx 42 months"},{"measure":"Health related Quality of Life","description":"EORTC QLQ-C30","timeFrame":"approx 42 months"}],"otherOutcomes":[{"measure":"biomarkers","description":"Ca-19-9, CEA, CRP serum levels","timeFrame":"approx 42 months"},{"measure":"Immunohistochemistry of Carboxylesterase (CES)","timeFrame":"approx 42 months"},{"measure":"Analyse whole blood","description":"will be collected to potentially identify factors that may correlate with tumour response, sensitivity or resistance to nal-IRI","timeFrame":"approx 42 months"},{"measure":"Analyse plasma","description":"will be collected to potentially identify factors that may correlate with tumour response, sensitivity or resistance to nal-IRI","timeFrame":"approx 42 months"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

1. Written informed consent incl. participation in translational research and any locally-required authorization (EU Data Privacy Directive in the EU) obtained from the subject prior to performing any protocol-related procedures, including screening evaluations
2. Age ≥ 18 years at time of study entry
3. Histologically or cytologically confirmed, non-resectable, locally advanced or metastatic cholangiocarcinoma or gall bladder carcinoma
4. Measurable or assessable disease according to RECIST 1.1
5. Documented disease progression after prior gemcitabine or gemcitabine containing therapy, in locally advanced or metastatic setting. Examples of permitted therapies include, but are not limited to:

   1. Single agent gemcitabine
   2. Any one gemcitabine-based regimen, with or without maintenance gemcitabine
6. ECOG performance status 0-1
7. Adequate blood count, liver-enzymes, and renal function:

   * ANC \> 1,500 cells/μL without the use of hematopoietic growth factors; and
   * Platelet count ≥ 100 x 10\^9/L (\>100,000 per mm³) and
   * Hemoglobin \> 9 g/dL (blood transfusions are permitted for patients with hemoglobin levels below 9 g/dL)
   * Serum total bilirubin ≤ 3x upper normal limit (ULN) (biliary drainage is allowed for biliary obstruction; elevated bilirubin should be caused by obstruction not impaired liver function as assessed by albumin and INR values):
   * Albumin levels ≥ 3.0 g/dL
   * Patients not receiving therapeutic anticoagulation must have an INR \< 1.5 ULN and PTT \< 1.5 ULN within 7 days prior to randomization. The use of full dose anticoagulants is allowed as long as the INR or PTT is within therapeutic limits (according to the medical standard in the institution) and the patient has been on a stable dose for anticoagulants for at least three weeks at the time of randomization
   * AST (SGOT)/ALT (SGPT) ≤ 5 x institutional upper limit of normal
   * Serum Creatinine ≤ 1.5 x ULN and a calculated glomerular filtration rate ≥ 30 mL per minute
8. Female patients with reproductive potential must have a negative urine or serum pregnancy test within 7 days prior to start of treatment.
9. Subject is willing and able to comply with the protocol (including contraceptive measures) for the duration of the study including undergoing treatment and scheduled visits and examinations including follow up.

Exclusion Criteria:

1. Active CNS metastases (indicated by clinical symptoms, cerebral oedema, steroid requirement, or progressive disease); patient should have been off steroids for at least 28 days prior to starting study therapy
2. Clinically significant gastrointestinal disorder including bleeding, inflammation, occlusion, or diarrhoea \> grade 1
3. History of any second malignancy in the last 5 years; subjects with prior history of in-situ cancer or basal or squamous cell skin cancer are eligible. Subjects with other malignancies are eligible if they have been continuously disease free for at least 5 years.
4. Active uncontrolled infection, chronic infectious diseases, immune deficiency syndromes or an unexplained fever \> 38.5°C during screening visits or on the first scheduled day of dosing (at the discretion of the investigator, patients with tumour fever may be enrolled), which in the investigator's opinion might compromise the patient's participation in the trial or affect the study outcome.
5. Premalignant hematologic disorders, e.g. myelodysplastic syndrome
6. Pre-existing lung disease
7. Clinically significant cardiovascular disease in (incl. myocardial infarction, unstable angina, symptomatic congestive heart failure, serious uncontrolled cardiac arrhythmia) 6 months before enrollment
8. History of hypersensitivity to any of the study drugs or any excipient (nal-IRI, other liposomal products, fluoropyrimidines or leucovorin)
9. Allogeneic transplantation requiring immunosuppressive therapy or other major immunosuppressive therapy
10. Severe non-healing wounds, ulcers or bone fractions
11. Evidence of bleeding diathesis or coagulopathy
12. Major surgical procedures, except open biopsy, nor significant traumatic injury within 28 days prior to randomization, or anticipation of the need for major surgical procedure during the course of the study except for surgery of central intravenous line placement for chemotherapy administration.
13. Medication that is known to interfere with any of the agents applied in the trial.
14. Female subjects who are pregnant, breast-feeding or male or female patients of reproductive potential who are not employing an effective method of birth control (failure rate of less than 1% per year). \[Acceptable methods of contraception are:implants, injectable contraceptives, combined oral contraceptives, intrauterine pessaries (only hormonal devices), sexual abstinence or vasectomy of the partner\].
15. Known Gilbert-Meulengracht syndrome
16. Any condition or comorbidity that, in the opinion of the investigator, would interfere with evaluation of study treatment or interpretation of patient safety or study results
17. Participation in another clinical study with an investigational product during the last 30 days before inclusion or 5 half-lifes of previously used trial medication, whichever is of longer duration.
18. Previous enrollment or randomization in the present study (does not include screening failure).
19. Previous enrollment in the NIFE trial \[AIO-YMO/HEP-0315\]
20. Involvement in the planning and/or conduct of the study (applies to both Baxalta staff and/or staff of sponsor and study site)
21. Patient who might be dependent on the sponsor, site or the investigator
22. Patient who has been incarcerated or involuntarily institutionalized by court order or by the authorities § 40 Abs. 1 S. 3 Nr. 4 AMG.
23. Patients who are unable to consent because they do not understand the nature, significance and implications of the clinical trial and therefore cannot form a rational intention in the light of the facts \[§ 40 Abs. 1 S. 3 Nr. 3a AMG\].","healthyVolunteers":false,"sex":"ALL","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"overallOfficials":[{"name":"Arndt Vogel, Prof.","affiliation":"Klinik für Gastroenterologie, Hepatologie und Endokrinologie, Medizinische Hochschule Hannover","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"Klinik für Gastroenterologie, Hepatologie und Endokrinologie, Medizinische Hochschule Hannover","city":"Hanover","zip":"30625","country":"Germany","geoPoint":{"lat":52.37052,"lon":9.73322}}]},"referencesModule":{"references":[{"pmid":"40147791","type":"DERIVED","citation":"Yoo C, Saborowski A, Hyung J, Wenzel P, Kim I, Wege H, Kim KP, Folprecht G, Ryoo BY, Schutt P, Cheon J, Gotze T, Ryu H, Lee JS, Vogel A. Liposomal irinotecan for previously treated patients with biliary tract cancer: A pooled analysis of NIFTY and NALIRICC trials. J Hepatol. 2025 Oct;83(4):909-916. doi: 10.1016/j.jhep.2025.03.013. Epub 2025 Mar 25."},{"pmid":"38870977","type":"DERIVED","citation":"Vogel A, Saborowski A, Wenzel P, Wege H, Folprecht G, Kretzschmar A, Schutt P, Jacobasch L, Ziegenhagen N, Boeck S, Zhang D, Kanzler S, Belle S, Mohm J, Gokkurt E, Lerchenmuller C, Graeven U, Pink D, Gotze T, Kirstein MM. Nanoliposomal irinotecan and fluorouracil plus leucovorin versus fluorouracil plus leucovorin in patients with cholangiocarcinoma and gallbladder carcinoma previously treated with gemcitabine-based therapies (AIO NALIRICC): a multicentre, open-label, randomised, phase 2 trial. Lancet Gastroenterol Hepatol. 2024 Aug;9(8):734-744. doi: 10.1016/S2468-1253(24)00119-5. Epub 2024 Jun 10."}],"seeAlsoLinks":[{"label":"AIO - Working Group for Medical Oncology from the German Cancer Society","url":"http://www.aio-portal.de"},{"label":"AIO-Studien-gGmbH","url":"http://www.aio-studien-ggmbh.de/projekte.html"}]},"ipdSharingStatementModule":{"ipdSharing":"NO"}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-11-24"},"interventionBrowseModule":{"meshes":[{"id":"C584112","term":"irinotecan sucrosofate"},{"id":"D005472","term":"Fluorouracil"},{"id":"D002955","term":"Leucovorin"}],"ancestors":[{"id":"D014498","term":"Uracil"},{"id":"D011744","term":"Pyrimidinones"},{"id":"D011743","term":"Pyrimidines"},{"id":"D006573","term":"Heterocyclic Compounds, 1-Ring"},{"id":"D006571","term":"Heterocyclic Compounds"},{"id":"D005575","term":"Formyltetrahydrofolates"},{"id":"D013763","term":"Tetrahydrofolates"},{"id":"D005492","term":"Folic Acid"},{"id":"D011622","term":"Pterins"},{"id":"D011621","term":"Pteridines"},{"id":"D006574","term":"Heterocyclic Compounds, 2-Ring"},{"id":"D000072471","term":"Heterocyclic Compounds, Fused-Ring"},{"id":"D003067","term":"Coenzymes"},{"id":"D045762","term":"Enzymes and Coenzymes"}]}},"hasResults":false},
{"protocolSection":{"identificationModule":{"nctId":"NCT07707947","orgStudyIdInfo":{"id":"CS-2025-07"},"organization":{"fullName":"Beijing Tiantan Hospital","class":"OTHER"},"briefTitle":"Selumetinib for NF2-Related Schwannomatosis","officialTitle":"A Single-Center, Single-Arm, Phase II Study to Explore the Efficacy and Safety of MEK1/2 Inhibitor (MEKi) Selumetinib in the Treatment of Patients With NF2-Related Schwannomatosis","acronym":"ASSIST"},"statusModule":{"statusVerifiedDate":"2026-10","overallStatus":"NOT_YET_RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2026-12-01","type":"ESTIMATED"},"primaryCompletionDateStruct":{"date":"2028-12-31","type":"ESTIMATED"},"completionDateStruct":{"date":"2028-12-31","type":"ESTIMATED"},"studyFirstSubmitDate":"2026-07-03","studyFirstSubmitQcDate":"2026-07-14","studyFirstPostDateStruct":{"date":"2026-07-16","type":"ACTUAL"},"lastUpdateSubmitDate":"2026-10-26","lastUpdatePostDateStruct":{"date":"2026-10-28","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Beijing Tiantan Hospital","class":"OTHER"},"collaborators":[{"name":"AstraZeneca","class":"INDUSTRY"}]},"oversightModule":{"oversightHasDmc":true,"isFdaRegulatedDrug":true,"isFdaRegulatedDevice":false,"isUsExport":true},"descriptionModule":{"briefSummary":"The goal of this clinical trial is to evaluate the efficacy and safety of the MEK1/2 inhibitor selumetinib in treating patients with neurofibromatosis type 2-related schwannomatosis (NF2-SWN), including both adults and children with inoperable or progressive tumors.","detailedDescription":"NF2-related schwannomatosis (NF2-SWN) is a rare, autosomal dominant tumor predisposition syndrome characterized by bilateral vestibular schwannomas and multifocal schwannomas arising from cranial, spinal, and peripheral nerves, frequently leading to progressive hearing loss, neurological deficits, and substantial morbidity. This study will serve as a Substudy component of the "Platform Research for Innovative Medicines in NF2-SWN (PRIME-NF2)" initiative, conducting a single-center, single-arm Phase II clinical trial aimed at evaluating the efficacy and safety of selumetinib in treating NF2-SWN-associated tumors. The study will enroll 20 patients diagnosed with NF2-related schwannomatosis (NF2-SWN) who have at least one measurable and progressive vestibular schwannoma and are aged ≥3 years. The primary endpoints include: ① Imaging response rate for NF2-SWN-associated vestibular schwannomas, assessed by a reduction of ≥20% in volume according to the REiNs criteria; ② Hearing response rate, defined as an improvement in speech recognition rate exceeding the 95% threshold difference. Secondary endpoints involve quality-of-life assessment: all patients will undergo evaluation using the NF2-SWN-specific Quality of Life Scale (NFTI-QOL), with additional pain scoring using the Numerical Rating Scale-11 (NRS-11) for patients with NF2-SWN-related intraspinal space-occupying lesions. The exploratory endpoints included: ① Imaging response rates for other NF2-SWN-related tumors excluding NF2-SWN-associated vestibular schwannomas: for meningiomas (non-vestibular schwannomas), objective imaging response defined as a volume reduction ≥20% per the REiNs criteria; for ependymomas, objective imaging response defined as a maximum diameter reduction ≥30% per the RECIST 1.1 criteria; total tumor burden; and the TSPO-PET/MRI-defined immune phenotype (immune-enriched vs. immune-depleted) and its association with treatment response in NF2-SWN-associated vestibular schwannomas. This study will provide further clinical evidence for targeted therapy of NF2-SWN."},"conditionsModule":{"conditions":["Neurofibromatosis Type 2","NF2","NF2-related Schwannomatosis","Meningioma","Ependymoma","Vestibular Schwannoma"],"keywords":["NF2-SWN","Selumetinib"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE2"],"designInfo":{"allocation":"NA","interventionModel":"SINGLE_GROUP","interventionModelDescription":"Selumetinib will be administered at a dose of 25 mg/m²orally twice daily (BID),with a maximum single dose of 50 mg per administration.Doses will be calculated based on body surface area (BSA)and rounded to the nearest 5 mg increment.","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":20,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Selumetinib","type":"EXPERIMENTAL","description":"Selumetinib will be administered at a dose of 25 mg/m²orally twice daily (BID),with a maximum single dose of 50 mg per administration.Doses will be calculated based on body surface area (BSA)and rounded to the nearest 5 mg increment.","interventionNames":["Drug: Selumetinib"]}],"interventions":[{"type":"DRUG","name":"Selumetinib","description":"Selumetinib will be administered at a dose of 25 mg/m²orally twice daily (BID),with a maximum single dose of 50 mg per administration.Doses will be calculated based on body surface area (BSA)and rounded to the nearest 5 mg increment.","armGroupLabels":["Selumetinib"],"otherNames":["KOSELUGO"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Objective Response Rate (ORR)in NF2-related vestibular schwannoma assessed according to the REiNS criteria","description":"Partial response is defined as the sum volume of VS decrease ≥20% compared to baseline, confirmed by a consecutive scan after 1 to 3 treatment cycles after the first response. Complete response is defined as disappearance of VS, confirmed by a consecutive scan after 1 to 3 treatment cycles after the first response;","timeFrame":"12 months"},{"measure":"Hearing Response Rate Based on Word Recognition Score (WRS) in Target Vestibular Schwannoma","description":"Percentage of participants with WRS improvement exceeding the 95% critical difference from baseline in the ear associated with the target vestibular schwannoma.","timeFrame":"12 months"},{"measure":"Pure Tone Average (PTA) Response Rate in Target Vestibular Schwannoma","description":"Percentage of participants with a PTA decrease of at least 10 dB from baseline in the ear associated with the target vestibular schwannoma.","timeFrame":"12 months"}],"secondaryOutcomes":[{"measure":"Assess safety and tolerability especially for selumetinib","description":"Incidence and severity of treatment -adverse events of ocular toxicity and cardiac toxicity graded according to CTCAE v6.0","timeFrame":"From the first dose of study drug (Day 0) through 30 ± 3 days after the last dose administration."}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

1. Patients must have a pathogenic variant in the NF2 gene (either in the germline or in two NF2-related tumors)OR a confirmed diagnosis of NF2 by fulfilling National Institute of Health (NIH)criteria or Manchester criteria:

   The genetic test report should be issued by companies or hospitals with corresponding qualifications.

   The NIH criteria includes presence of:
   * Bilateral vestibular schwannomas, OR
   * First-degree relative with NF2 and EITHER unilateral eighth nerve mass OR two of the following: neurofibroma, meningioma, glioma, schwannoma, juvenile posterior subcapsular lenticular opacity.

   The Manchester criteria includes presence of:
   * Bilateral vestibular schwannomas, OR
   * First-degree relative with NF2 and EITHER unilateral eighth nerve mass OR two of the following: neurofibroma, meningioma, glioma, schwannoma, juvenile posterior subcapsular lenticular opacity, OR
   * Unilateral vestibular schwannoma AND any two of: neurofibroma, meningioma, glioma, schwannoma, juvenile posterior subcapsular lenticular opacity,OR
   * Multiple meningiomas (two or more)AND unilateral vestibular schwannoma OR
   * any two of: schwannoma, glioma, neurofibroma, cataract.
2. Subjects must have ≥1 measurable target vestibular schwannoma meeting all of the following conditions:

   * Measurable on MRI with a minimum diameter ≥3 mm;
   * Evidence of radiographic progression within the past 36 months according to REiNS criteria, OR documented clinical progression attributable to the target tumor (e.g., hearing decline, cranial nerve dysfunction).
   * Subjects whose Word Recognition Score (WRS)ranging from 50%to 88%at the side of target vestibular schwannoma.
3. The target tumor must be considered not amenable to surgery due to:

   * High surgical risk (e.g., risk of neurological deficit), OR
   * Patient refusal of surgery after adequate medical counseling.
4. Male or female subjects aged ≥3 years at the time of informed consent.
5. Adequate functional status

   Subjects aged ≥16 years:
   * Karnofsky Performance Status ≥70,OR
   * ECOG Performance Status 0-1

   Subjects aged \<16 years:
   * Lansky Performance Status ≥70
   * Adequate organ and bone marrow function
6. Laboratory values obtained within 28 days prior to enrollment must meet the following:

   1. Hematologic function

      * Hemoglobin ≥9.0 g/dL
      * Absolute neutrophil count (ANC)≥1.5 ×10⁹/L
      * Platelet count ≥100 ×10⁹/L
   2. Hepatic function

      * AST and ALT ≤2.5 ×ULN (≤2.0 ×ULN for pediatric subjects)
      * Total bilirubin ≤ 1.5 ×ULN (≤3 ×ULN in subjects with documented Gilbert's syndrome)
   3. Renal function

      * Serum creatinine ≤1.5 ×ULN, OR
      * Creatinine clearance ≥60 mL/min/1 .73 m²(age-and BSA-adjusted)
   4. Cardiac function

      * Left ventricular ejection fraction (LVEF)≥50%by echocardiography
      * No clinically significant uncontrolled cardiac disease
   5. Pulmonary function • Peripheral oxygen saturation ≥92%on room air
7. Reproductive and contraception requirements

   1. Females of childbearing potential

      * Negative serum or urine pregnancy test prior to enrollment
      * Must be postmenopausal ≥12 months, surgically sterile, or using a highly effective method of contraception throughout the study and for 3 months after the last dose
      * Acceptable methods include:

        * Hormonal contraception
        * Intrauterine device (IUD)
        * Long-acting reversible contraception
        * Tubal ligation
      * Oral contraception alone must be combined with a barrier method
   2. Males • Must be surgically sterile or agree to use barrier contraception with permicide during treatment and for 3 months after the last dose.
8. Subjects must be able to swallow selumetinib capsules intact.
9. Written informed consent must be obtained:

   * From the subject if capable of providing consent;
   * From a legally acceptable representative for minors or subjects lacking full decision-making capacity.

Exclusion Criteria:

1. Concurrent involvement in study conduct:the subject is an employee of the Sponsor, Investigator, or study site who is directly involved in the planning, conduct, or management of this clinical study.
2. Participation in another interventional clinical trial with an investigational medicinal product, or receipt of an investigational agent within 28 days (or 5 half-lives if known and longer)prior to first dose.
3. Prior anti-cancer systemic therapies or prior radiotherapy that, in the investigator's judgment, would confound safety or efficacy assessment, unless completed ≥28 days prior to first dose (longer washout required for agents with prolonged biologic effect as specified in protocol appendix). Subjects who received prior local therapy (surgery or localized radiotherapy)are eligible if recovery is complete and target lesion remains measurable.
4. Evidence or high suspicion of malignant peripheral nerve sheath tumor (MPNST)or other active malignancy requiring systemic therapy (past malignancy is allowed only if disease-free for ≥2 years, except for adequately treated basal cell carcinoma or in situ carcinoma).
5. Significant cardiac disease or ECG abnormalities:

   * Resting QTcF \>470 ms (adults)\[\>450 ms for pediatric thresholds as specified in protocol appendix\], or clinically significant baseline prolongation per investigator/medical monitor.
   * Clinically significant arrhythmia (symptomatic ventricular tachycardia, sustained ventricular tachycardia, uncontrolled atrial fibrillation). Subjects with well controlled atrial fibrillation may be considered after Medical Monitor review.
   * Acute coronary syndrome within 6 months, unstable angina, symptomatic congestive heart failure NYHA class II-IV, or LVEF below institutional lower limit of normal (LLN)or \<50%.
6. Uncontrolled hypertension:systolic ≥140 mmHg or diastolic ≥90 mmHg despite optimal therapy (adult criteria);for pediatric subjects use age/height/gender percentiles per protocol appendix.
7. Severe hepatic or renal impairment -e.g.,AST/ALT \>5 ×ULN (or per protocol specified threshold for severe impairment), total bilirubin \>3 ×ULN (unless Gilbert's syndrome).(See inclusion for minimum acceptable labs;exclude those with more severe dysfunction.)
8. Ophthalmologic conditions:current or prior history of MEK-associated retinopathy / central serous retinopathy /retinal pigment epithelial detachment /retinal vein occlusion, or any active ocular condition judged by the investigator/ophthalmologist to increase the risk of serious ocular adverse events (e.g., uncontrolled glaucoma with elevated IOP and meaningful vision at risk). Subjects with stable, chronic ophthalmic findings that are not expected to worsen with MEK inhibition may be eligible after ophthalmology clearance.
9. Known hypersensitivity to selumetinib or any excipients.
10. Active, uncontrolled infection including:

    * Positive HIV test (known HIV infection with uncontrolled disease or on unstable antiretroviral therapy that interacts with study drug)-no evidence AIDS and no contraindicating ART may be considered after Medical Monitor review.
    * Active hepatitis B or C infection (HBsAg positive or HCV RNA positive). Subjects with resolved HBV (HBsAg negative, anti-HBc positive)may be eligible per local hepatology guidance and prophylaxis plan.
11. Concomitant medications that:

    * Are known to prolong QT interval and cannot be safely discontinued;OR
    * Are strong CYP3A4 or CYP2C19 inducers/inhibitors that cannot be stopped and would significantly alter selumetinib exposure (refer to protocol drug-interaction appendix for permitted/forbidden lists).
12. Gastrointestinal conditions that preclude reliable oral absorption (e.g., severe malabsorption, short bowel syndrome, recent (within 6 months)major intestinal resection)or inability to swallow intact capsules.
13. Conditions requiring urgent neurosurgical intervention (e.g., symptomatic hydrocephalus requiring immediate shunting, life-threatening brainstem compression)-subjects requiring emergent neurosurgery are not eligible until stabilized and reevaluated.
14. Prior organ transplantation (allogeneic)or ongoing immunosuppression that would confound safety assessment.
15. Concomitant vitamin E†or other agents judged to have potential interaction with the study drug if they cannot be discontinued per protocol (e.g., vitamin E to be stopped ≥7 days before first dose if required by protocol).
16. Pregnancy or breastfeeding at screening (positive pregnancy test). Female subjects of childbearing potential who are unwilling/unable to use acceptable contraception during the study and for the duration specified in the contraceptive guidance (see protocol)are excluded.
17. Any other clinically significant medical, psychiatric, or social condition that, in the opinion of the investigator or Medical Monitor, would compromise subject safety or protocol compliance (including inability to undergo MRI, when MRI is required for tumor assessment).","healthyVolunteers":false,"sex":"ALL","minimumAge":"3 Years","stdAges":["CHILD","ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"centralContacts":[{"name":"Pinan Liu, PhD","role":"CONTACT","phone":"010-59976611","email":"pinanliu@ccmu.edu.cn"}],"locations":[{"facility":"Beijing Tiantan Hospital, Capital Medical University","city":"Beijing","state":"Beijing Municipality","zip":"100070","country":"China","contacts":[{"name":"Pinan Liu, PhD","role":"CONTACT","phone":"010-59976611","email":"pinanliu@ccmu.edu.cn"}],"geoPoint":{"lat":39.9075,"lon":116.39723}}]},"ipdSharingStatementModule":{"ipdSharing":"NO","description":"Individual participant data will not be shared. This decision is based on: (1) the rare disease nature of NF2-SWN and small sample size (n=20), which increases re-identification risk even after de-identification; (2) protection of participant privacy and confidentiality as required by Chinese ethics regulations and the informed consent process; and (3) proprietary considerations of the study sponsor regarding investigational product data."}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-11-24"},"conditionBrowseModule":{"meshes":[{"id":"D016518","term":"Neurofibromatosis 2"},{"id":"D008579","term":"Meningioma"},{"id":"D004806","term":"Ependymoma"},{"id":"D009464","term":"Neuroma, Acoustic"}],"ancestors":[{"id":"D009442","term":"Neurilemmoma"},{"id":"D018358","term":"Neuroendocrine Tumors"},{"id":"D017599","term":"Neuroectodermal Tumors"},{"id":"D009373","term":"Neoplasms, Germ Cell and Embryonal"},{"id":"D009370","term":"Neoplasms by Histologic Type"},{"id":"D009369","term":"Neoplasms"},{"id":"D017253","term":"Neurofibromatoses"},{"id":"D009455","term":"Neurofibroma"},{"id":"D018317","term":"Nerve Sheath Neoplasms"},{"id":"D009380","term":"Neoplasms, Nerve Tissue"},{"id":"D009463","term":"Neuroma"},{"id":"D009386","term":"Neoplastic Syndromes, Hereditary"},{"id":"D000160","term":"Vestibulocochlear Nerve Diseases"},{"id":"D012181","term":"Retrocochlear Diseases"},{"id":"D004427","term":"Ear Diseases"},{"id":"D010038","term":"Otorhinolaryngologic Diseases"},{"id":"D010039","term":"Otorhinolaryngologic Neoplasms"},{"id":"D003390","term":"Cranial Nerve Neoplasms"},{"id":"D003389","term":"Cranial Nerve Diseases"},{"id":"D009422","term":"Nervous System Diseases"},{"id":"D020752","term":"Neurocutaneous Syndromes"},{"id":"D020271","term":"Heredodegenerative Disorders, Nervous System"},{"id":"D019636","term":"Neurodegenerative Diseases"},{"id":"D030342","term":"Genetic Diseases, Inborn"},{"id":"D009358","term":"Congenital, Hereditary, and Neonatal Diseases and Abnormalities"},{"id":"D009383","term":"Neoplasms, Vascular Tissue"},{"id":"D008577","term":"Meningeal Neoplasms"},{"id":"D016543","term":"Central Nervous System Neoplasms"},{"id":"D009423","term":"Nervous System Neoplasms"},{"id":"D009371","term":"Neoplasms by Site"},{"id":"D005910","term":"Glioma"},{"id":"D018302","term":"Neoplasms, Neuroepithelial"},{"id":"D009375","term":"Neoplasms, Glandular and Epithelial"},{"id":"D010524","term":"Peripheral Nervous System Neoplasms"}]},"interventionBrowseModule":{"meshes":[{"id":"C517975","term":"AZD 6244"}]}},"hasResults":false},
{"protocolSection":{"identificationModule":{"nctId":"NCT05837533","orgStudyIdInfo":{"id":"EC-COMUNICACION"},"organization":{"fullName":"Medicos e Investigadores en la Lucha contra el Cancer de Mama","class":"OTHER"},"briefTitle":"Multicenter Study to Evaluate a Systematized Communication Model for Breast Cancer Patients","officialTitle":"Multicenter Study to Evaluate the Impact of a Systematized Communication Model to Increase the Knowledge of Breast Cancer Patients About Their Disease"},"statusModule":{"statusVerifiedDate":"2025-02","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2023-05-17","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2024-11-16","type":"ACTUAL"},"completionDateStruct":{"date":"2024-11-16","type":"ACTUAL"},"studyFirstSubmitDate":"2023-04-19","studyFirstSubmitQcDate":"2023-04-28","studyFirstPostDateStruct":{"date":"2023-05-01","type":"ACTUAL"},"lastUpdateSubmitDate":"2025-02-05","lastUpdatePostDateStruct":{"date":"2025-02-07","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Medicos e Investigadores en la Lucha contra el Cancer de Mama","class":"OTHER"}},"oversightModule":{"oversightHasDmc":false,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false,"isUsExport":false},"descriptionModule":{"briefSummary":"Both in Mexico and in the world, breast cancer is the most common malignancy in women. It is estimated that in 2020, 28.2% of the new cancer cases reported in our country correspond to breast cancer, which translates to 30,000 new cases. In addition, it is relevant to mention that approximately 12% of Mexican patients are diagnosed with stage IV breast cancer and it is estimated that 20-30% of women with early stage cancer will have a distant recurrence of the disease. Thus, about 40% of patients will find themselves in a metastatic stage at some point in their breast cancer journey.

Various studies, including Mexico, report that only half of patients with metastatic breast cancer are aware that their disease is not curable, 31% say they are not sure, and 17% think it is curable. Likewise, 58% considered that they did not have enough knowledge to actively participate in conversations about their therapeutic options, which means that 40% reported difficulty talking about treatments with their doctors. This has shown that there are suboptimal levels of knowledge information on curability, treatment objectives and prognosis of their condition in patients with metastatic breast cancer. This lack of understanding is alarming given that a general understanding of the disease is crucial for informed decision making and adherence to cancer treatment.

Due to these alarming results, we seek to recruit women ≥18 years of age who are candidates to start first- or second-line treatment for de novo or recurrent metastatic breast cancer from various hospital centers in the country with public and private coverage, including Hospital Zambrano Hellion TecSalud as coordinating center in Nuevo León. The objective will be to evaluate whether a systematized communication model for patients with metastatic breast cancer allows increasing knowledge about the non-curative nature of treatment, compared to usual care."},"conditionsModule":{"conditions":["Breast Cancer Stage IV","Breast Cancer Metastatic","Communication"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"NON_RANDOMIZED","interventionModel":"SEQUENTIAL","interventionModelDescription":"During the first half of the study, patients will be assigned to the control group where they will receive information through their usual care from their oncologist during their medical consultation. In the second half of the study, patients will be assigned to the intervention group where they will receive information through the communication model used by their oncologist during their medical consultation. In this way, the contamination of the control group with attention corresponding to the systematized communication model under study will be avoided.","primaryPurpose":"OTHER","maskingInfo":{"masking":"DOUBLE","maskingDescription":"Participants will not be informed whether they will be allocated to the control or intervention group.","whoMasked":["PARTICIPANT","OUTCOMES_ASSESSOR"]}},"enrollmentInfo":{"count":100,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Intervention group","type":"EXPERIMENTAL","description":"Patients will receive information about their diagnosis, treatment and/or prognosis through the systematic communication model under study used by their oncologist during their medical consultation.","interventionNames":["Other: Communication model"]},{"label":"Control group","type":"NO_INTERVENTION","description":"Patients will receive information about their diagnosis, treatment and/or prognosis through their usual care provided by their oncologist during their medical consultation."}],"interventions":[{"type":"OTHER","name":"Communication model","description":"During the medical consultation of each patient assigned to the intervention group, the oncologist will use the systematic communication model for patients with metastatic breast cancer. For this, the oncologist will follow the conversation guide for patients with metastatic breast cancer, which will allow directing the conversation towards information about the patient's diagnosis, treatment and prognosis. The guide consists of a series of steps and questions to be asked to the patient in order to explore her understanding of her disease and her information preferences, as well as to facilitate the oncologist providing said information to the patient. The responses to each item in the guide will be electronically documented by the oncologist.","armGroupLabels":["Intervention group"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Patient understanding","description":"Evaluate whether a systematic communication model for patients with metastatic breast cancer increases patients' understanding about the non-curative nature of treatment, compared to usual care. Understanding will be measured with the "Knowledge questionnaire" consisting of the Prognosis and Treatment Perceptions Questionnaire (PTPQ) questions, which explore patients' beliefs about their possibility of cure and the main objective of their treatment, their perception of the importance and usefulness of knowing their prognosis, their information preferences, as well as their satisfaction with the quality of the information received. Additionally, the research group developed specific questions that are of interest for this study to assess participants' perception of the usefulness of the information received through the systematic communication model, as well as their use of the information materials provided and their degree of satisfaction with them.","timeFrame":"7 days"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Diagnosis of de novo or recurrent metastatic breast cancer
* Candidate to start the first or second line of treatment for metastatic breast cancer

Exclusion Criteria:

* Receipt of a line of treatment for metastatic breast cancer posterior to the second line","healthyVolunteers":false,"sex":"FEMALE","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"locations":[{"facility":"Hospital Zambrano Hellion","city":"San Pedro Garza García","state":"Nuevo León","zip":"66278","country":"Mexico","geoPoint":{"lat":25.66158,"lon":-100.4034}}]},"ipdSharingStatementModule":{"ipdSharing":"NO"}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-11-24"},"conditionBrowseModule":{"meshes":[{"id":"D001943","term":"Breast Neoplasms"},{"id":"D003142","term":"Communication"}],"ancestors":[{"id":"D009371","term":"Neoplasms by Site"},{"id":"D009369","term":"Neoplasms"},{"id":"D001941","term":"Breast Diseases"},{"id":"D012871","term":"Skin Diseases"},{"id":"D017437","term":"Skin and Connective Tissue Diseases"},{"id":"D001519","term":"Behavior"}]}},"hasResults":false},
{"protocolSection":{"identificationModule":{"nctId":"NCT05490433","orgStudyIdInfo":{"id":"4-2022-0600"},"organization":{"fullName":"Yonsei University","class":"OTHER"},"briefTitle":"Robot-assisted vs. Open Nipple-sparing Mastectomy With Immediate Breast Reconstruction","officialTitle":"A Prospective Multicenter Randomized Clinical Trial: Robot-assisted vs. Open Nipple-sparing Mastectomy With Immediate Breast Reconstruction (ROM) Trial","acronym":"ROM"},"statusModule":{"statusVerifiedDate":"2025-11","overallStatus":"RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2022-10-26","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2032-06","type":"ESTIMATED"},"completionDateStruct":{"date":"2032-06","type":"ESTIMATED"},"studyFirstSubmitDate":"2022-08-03","studyFirstSubmitQcDate":"2022-08-03","studyFirstPostDateStruct":{"date":"2022-08-05","type":"ACTUAL"},"lastUpdateSubmitDate":"2025-11-14","lastUpdatePostDateStruct":{"date":"2025-11-17","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Yonsei University","class":"OTHER"}},"oversightModule":{"oversightHasDmc":true,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"Research Purpose The present study is designed to generate the strongest evidence available on the role of robotic surgical systems in breast cancer surgery and to elucidate the clinical value of immediate breast reconstruction (IBR) conducted in conjunction with robot-assisted nipple-sparing mastectomy (RNSM).

Study Design Overview This study is a prospective, multicenter, randomized clinical trial (ROM Trial) designed to compare the oncologic outcomes of robot-assisted nipple-sparing mastectomy (RNSM) with conventional nipple-sparing mastectomy (CNSM), which includes both traditional and open-chest approaches. Previous retrospective studies of robot-assisted endoscopic surgery have suggested a short learning curve, demonstrating technical feasibility and reproducibility even for less experienced surgeons. However, the absence of rigorously designed randomized clinical trials remains a major global barrier to the broader adoption of robotic breast surgery.

In the ROM Trial, eligible patients who provide written informed consent will be randomly assigned in a 1:1 ratio to undergo either RNSM or CNSM. Participants will be blinded to group allocation until the day of surgery (single-blind design). Immediate breast reconstruction (IBR) will be performed in all patients, with the reconstruction method determined in consultation with the breast and/or plastic surgeon following mastectomy.","detailedDescription":"Background Robot-assisted nipple-sparing mastectomy (RNSM) has emerged as an approach for both breast cancer treatment and risk-reducing mastectomy in women carrying high-risk pathogenic variants. Although several studies have reported that RNSM is a feasible procedure, concerns remain that it is performed only by a small number of specialized surgeons, and data on oncologic outcomes and patient-reported outcomes (PROs) remain limited. Recently, the United States Food and Drug Administration and several expert surgeons have cautioned that robotic breast surgery should be performed only by highly trained specialists, and that the benefits, risks, and alternative treatment options must be thoroughly discussed with patients to ensure fully informed decision-making.

To promote the safe and standardized application of RNSM, the Korea Robot-Endoscopy Minimal Access Breast Surgery Study Group (KoREa-BSG) was established with the mission to evaluate, standardize, and disseminate this advanced surgical technique.

Study Design We designed a prospective, multicenter, randomized clinical trial (Robot vs. Open Nipple-sparing Mastectomy Trial; ROM Trial) to evaluate the oncologic outcomes of RNSM with immediate breast reconstruction (IBR), compared with conventional open nipple-sparing mastectomy (CNSM) with IBR.

Previous retrospective studies on robot-assisted endoscopic breast surgery have demonstrated a short learning curve, suggesting that the technique is feasible and reproducible even for less experienced surgeons. However, the absence of rigorously designed randomized controlled trials has been a major limitation in expanding the global adoption of robotic breast surgery. The ROM Trial was therefore established to address this unmet need.

Data Collection Clinical and pathological data to be collected include: height, weight, breast volume/weight, age, germline likely pathogenic/pathogenic mutation status, affected breast, bilaterality, breast ptosis, tumor size, TNM stage, histologic grade, histologic type, estrogen receptor (ER), progesterone receptor (PR), human epidermal growth factor receptor 2 (HER2), Ki-67 index, nipple involvement, neoadjuvant/adjuvant treatment status, postoperative complications (Clavien-Dindo classification), operative time, margin involvement, postoperative drainage amount/duration, risk-reducing mastectomy (RRM) status, reconstruction type, recurrence status, healthcare cost data, and follow-up information.

Patient Satisfaction Assessment Between 3 and 12 months (±30 days) after the final surgery, patients will be surveyed using the validated Korean version of the BREAST-Q questionnaire to evaluate satisfaction with surgery.

Cost-Effectiveness Assessment (Optional) Cost-effectiveness according to surgical method will be evaluated between 3 and 12 months (±30 days) after the final surgery, using the Korean version of the EuroQol 5-Dimension (EQ-5D) questionnaire."},"conditionsModule":{"conditions":["Breast Cancer Classified as TNM Stage 0-IIIa"],"keywords":["Breast cancer"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","interventionModelDescription":"RNSM and CNSM procedures are systematic at 1:1 ratio after obtaining consent forms for research participation and checking criteria for exclusion from selection It is randomly assigned from the award. The patient is subjected to a single blind examination so that the surgical method is unknown before surgery.

Reconstruction methods after resection are discussed with breast and/or plastic surgeons","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"SINGLE","whoMasked":["PARTICIPANT"]}},"enrollmentInfo":{"count":790,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"robot assisted nipple sparing mastectomy(RNSM)","type":"EXPERIMENTAL","description":"Robotic nipple sparing mastectomy, robotic mastectomy, hybrid robotic nipple sparing mastectomy, robotic nipple mammary complex and skin sparing mastectomy, robot nipple sparing mastectomy","interventionNames":["Procedure: Robot-assisted Nipple-Sparing Mastectomy (RNSM)"]},{"label":"Conventional nipple sparing mastectomy(CNSM)","type":"ACTIVE_COMPARATOR","description":"Total mastectomy, mastectomy, nipple sparing mastectomy, skin sparing mastectomy, nipple sparing breast resection, open nipple sparing mastectomy, general nipple sparing Mammastectomy, an open-window nipple sparing mastectomy","interventionNames":["Procedure: Conventional nipple sparing mastectomy(CNSM)"]}],"interventions":[{"type":"PROCEDURE","name":"Robot-assisted Nipple-Sparing Mastectomy (RNSM)","description":"Patients undergoing robot-assisted nipple-sparing mastectomy (RNSM) with immediate breast reconstruction (IBR) will be enrolled in this group. RNSM will be performed using robotic surgical platforms, including the da Vinci S, Si, X, Xi, and SP systems. The procedure will be conducted through an axillary or lateral chest wall incision.

During surgery, posterior areolar tissue sampling for frozen section biopsy will be recommended. If suspicious lesions are detected at the superficial or posterior margins, frozen section biopsy of those lesions will also be performed. When tumor involvement of the nipple-areola complex (NAC), superficial margin, or posterior margin is confirmed by frozen section biopsy, additional resection including the skin and NAC, or postoperative radiotherapy, will be considered.","armGroupLabels":["robot assisted nipple sparing mastectomy(RNSM)"]},{"type":"PROCEDURE","name":"Conventional nipple sparing mastectomy(CNSM)","description":"Patients who undergo conventional nipple-sparing mastectomy (CNSM) with immediate breast reconstruction (IBR) will be enrolled in this group. CNSM is performed without the use of robotic or endoscopic surgical systems, and all types of skin incisions are permitted.

During surgery, posterior areolar tissue sampling for frozen section biopsy is recommended. If suspicious lesions suggesting tumor involvement are identified at the superficial or posterior margins, frozen section biopsy should also be performed. When frozen section biopsy confirms tumor involvement of the nipple-areola complex (NAC), superficial margin, or posterior margin, additional excision including the skin and NAC, or postoperative radiotherapy, will be considered.","armGroupLabels":["Conventional nipple sparing mastectomy(CNSM)"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"5-year disease-free survival rate(DFS)","description":"From the date of surgery to the first qualifying event, or censored at the date of last follow-up if no event occurs

* Events: local/regional/distant recurrence, contralateral breast cancer, or all-cause mortality.
* Local recurrence: recurrence in the ipsilateral breast or chest muscles, ipsilateral chest wall, or nipple-areola complex (NAC).
* Regional recurrence: recurrence in the ipsilateral axillary lymph nodes, ipsilateral infra/supraclavicular lymph nodes, or ipsilateral internal mammary lymph nodes.
* intraepithelial carcinoma is included as an event for local recurrence and contralateral breast cancer.
* patients without an event are censored at the last known disease assessment.

Statistical analysis (non-inferiority)

* DFS will be analyzed using a Cox proportional hazards model stratified by institution and clinical stage.
* The hazard ratio (HR) for RNSM vs CNSM and its 95% confidence interval (CI) will be estimated.","timeFrame":"The DFS period is calculated from the date of surgery to the time of the first event, or censored at the date of last follow-up if no event is reported."}],"secondaryOutcomes":[{"measure":"5-Year Overall Survival (OS)","description":"Events for OS are defined as death from any cause. OS time will be calculated in months from the date of surgery to the date of the event.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"},{"measure":"5-Year Breast Cancer-Specific Survival (BCSS)","description":"Events for BCSS include death attributable to breast cancer. Deaths from unrelated causes will be censored.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"},{"measure":"5-Year Distant Recurrence-Free Survival (DRFS)","description":"Events for DRFS are defined as the first occurrence of distant recurrence. Local recurrence and contralateral breast cancer will be censored.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"},{"measure":"5-Year Locoregional Recurrence-Free Survival (LRFS)","description":"Events for LRFS include the first occurrence of local or regional recurrence. Distant recurrence and contralateral breast cancer will be censored.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"},{"measure":"5-Year Nipple Recurrence Rate (NR)","description":"NR is defined as the first recurrence of the nipple-areola complex (NAC). Recurrence in the ipsilateral breast or chest muscles, chest wall, regional lymph nodes, contralateral breast, or distant sites will be censored.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"},{"measure":"Positive Margin Rate (at Surgery)","description":"A positive margin is defined as tumor involvement of the NAC, superficial, posterior, or circumferential margins confirmed in the final pathology report. The overall positive margin rate will be analyzed.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"},{"measure":"Conversion Rate to Open Surgery (RNSM Group Only; at Surgery)","description":"In the RNSM group, intraoperative conversion from RNSM to CNSM will be analyzed. Reasons for conversion will be documented.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"},{"measure":"Operation time","description":"Total operative time includes both mastectomy and reconstruction. Each component will be measured separately and analyzed.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"},{"measure":"30-Day Postoperative Complication Rate","description":"The complication rate within 30 days post-surgery will be calculated as the total number of complications per patient in each group. Both the total number of complications per patient and the number of Clavien-Dindo grade III or higher complications per patient will be analyzed. NAC necrosis rate will also be evaluated.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"},{"measure":"Clavien-Dindo Classification of Postoperative Complications (within 180 days)","description":"Postoperative complications will be assessed using the Clavien-Dindo classification. Grade III or higher complications, including flap or implant loss, will be analyzed.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"},{"measure":"Flap or Implant Loss Rate (within 1 year postoperatively)","timeFrame":"Flap or implant loss within 1 year of surgery will be recorded and analyzed."},{"measure":"Patient-Reported Outcomes (between 3 and 12 months postoperatively)","description":"Breast satisfaction will be evaluated using the BREAST-Q version 2.0 scale administered before and after mastectomy. Higher scores indicate better outcomes.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"},{"measure":"Surgeon Satisfaction (between 3 and 12 months postoperatively)","description":"Surgical satisfaction will be evaluated by the operating surgeon. Overall symmetry, postoperative scarring, and NAC symmetry will be scored using a 0-10 scale, with higher scores indicating better outcomes.

Overall symmetry, postoperative scar, and NAC symmetry are measured using scoring system 0-10. The higher scores are, the better an outcome is.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"},{"measure":"Cost-Effectiveness (between 3 and 12 months postoperatively; optional)","description":"Cost-effectiveness will be assessed between 3 and 12 months after the final surgery using the Korean version of the EuroQol 5-Dimension (EQ-5D) questionnaire. Higher scores indicate better outcomes across all dimensions.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"},{"measure":"30-Day Estimated Postoperative Complication Rate","description":"Based on a sample size of 790 (632 after accounting for 20% dropout), the study has at least 80% power to detect various assumed complication rates between the conventional and robotic groups, with a non-inferiority margin of 7.5%. The assumed 30-day complication rate for the conventional group is 25-50%. The maximum 30-day complication rate for the robotic group to be considered non-inferior is presented in Table 2. These will be analyzed as secondary endpoints.","timeFrame":"secondary outcome is calculated from the date of surgery to the time the first event occurs, or if the event is not reported on the last follow-up date.(After 5 years of follow-up observation of subject registration)"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Adult women (≥19 years) scheduled to undergo therapeutic mastectomy for breast cancer who desire immediate breast reconstruction (IBR).
* Breast cancer classified as clinical TNM stage 0 to IIIA, based on preoperative evaluation according to the 8th edition of the AJCC anatomic staging system.
* Eastern Cooperative Oncology Group (ECOG) performance status of 0 or 1.

Exclusion Criteria:

* Patients scheduled for breast-conserving surgery or deemed ineligible for immediate breast reconstruction (IBR).
* Clinical evidence of nipple or skin involvement on preoperative evaluation.

  * Pregnant or breastfeeding women.
  * Tumors consisting exclusively of lobular carcinoma in situ (LCIS).
  * Paget's disease of the breast.
  * Inflammatory breast cancer.
  * Male breast cancer.
  * Clinical stage IIIB-IV disease on preoperative evaluation.
  * breast size equal to or larger than cup E
  * History of breast cancer or bilateral breast cancer (including metachronous or synchronous disease).
  * History of non-breast malignancy, with the exception of non-melanoma skin cancer or papillary/follicular thyroid carcinoma.
  * Special histologic subtypes of breast tumors (e.g., phyllodes tumor, sarcoma, lymphoma).
  * Age \>70 years.
  * American Society of Anesthesiologists (ASA) physical status classification grade ≥4.
  * Inability to provide informed consent.
  * History of prior chest radiotherapy.
  * Patients who have not undergone preoperative testing for hepatitis B virus (HBV), hepatitis C virus (HCV), and human immunodeficiency virus (HIV), which is required for liability insurance coverage.","healthyVolunteers":false,"sex":"FEMALE","genderBased":true,"minimumAge":"19 Years","maximumAge":"70 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"centralContacts":[{"name":"Hyung Seok Park, MD, PhD","role":"CONTACT","phone":"82-10-6760-2974","email":"imgenius@yuhs.ac"}],"overallOfficials":[{"name":"Hyung Seok Park, MD, PhD","affiliation":"Yonsei University","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"Samsung Changwon Medical Center","status":"RECRUITING","city":"Changwon","country":"South Korea","contacts":[{"name":"Hee Jun Choi, M.D. PhD","role":"CONTACT","phone":"82-10-9955-5801","email":"heejun1.choi@samsung.com"}],"geoPoint":{"lat":35.22806,"lon":128.68111}},{"facility":"Keimyung University Dongsan Hospital","status":"RECRUITING","city":"Daegu","country":"South Korea","contacts":[{"name":"Moo Hyun Lee, MD","role":"CONTACT","phone":"82-10-2315-0197","email":"mhlee197@gmail.com"}],"geoPoint":{"lat":35.87102,"lon":128.60121}},{"facility":"Kyungpook National University Chilgok Hospital","status":"RECRUITING","city":"Daegu","country":"South Korea","contacts":[{"name":"Jeeyeon Lee, MD, PhD","role":"CONTACT","phone":"82-10-5134-0001","email":"j.lee@knu.ac.kr"}],"geoPoint":{"lat":35.87102,"lon":128.60121}},{"facility":"Yeungnam University Medical Center","status":"NOT_YET_RECRUITING","city":"Daegu","country":"South Korea","contacts":[{"name":"Jeong eun Choi, MD, PhD","role":"CONTACT","phone":"82-10-2524-7017","email":"cjegs@yu.ac.kr"}],"geoPoint":{"lat":35.87102,"lon":128.60121}},{"facility":"Myongji Hospital","status":"RECRUITING","city":"Goyang-si","country":"South Korea","contacts":[{"name":"Hyukjai Shin, M.D. PhD","role":"CONTACT","phone":"82 10 8803 5433","email":"drgsshj@gmail.com"}],"geoPoint":{"lat":37.65639,"lon":126.835