{"protocolSection":{"identificationModule":{"nctId":"NCT05613348","orgStudyIdInfo":{"id":"2022-KY-094"},"organization":{"fullName":"Zhujiang Hospital","class":"OTHER"},"briefTitle":"CD19 CAR T-cell Target Relapsed/Refractory Acute B Cell Leukemia/Lymphoma","officialTitle":"Humanized CAR19T2 T Cell in Children With Refractory/Relapsed B-cell Leukemia/Lymphoma","acronym":"CAR19T2"},"statusModule":{"statusVerifiedDate":"2022-10","overallStatus":"WITHDRAWN","whyStopped":"The company failed to provide corresponding CART services.","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2022-12-01","type":"ESTIMATED"},"primaryCompletionDateStruct":{"date":"2025-12-01","type":"ESTIMATED"},"completionDateStruct":{"date":"2028-12-01","type":"ESTIMATED"},"studyFirstSubmitDate":"2022-10-13","studyFirstSubmitQcDate":"2022-11-04","studyFirstPostDateStruct":{"date":"2022-11-14","type":"ACTUAL"},"lastUpdateSubmitDate":"2024-03-14","lastUpdatePostDateStruct":{"date":"2024-03-18","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Zhujiang Hospital","class":"OTHER"},"collaborators":[{"name":"Guangdong Zhaotai Cell Bio-tech Co., LTD","class":"UNKNOWN"}]},"oversightModule":{"oversightHasDmc":false,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"This study aims to evaluate the safety and efficacy of humanized Anti-CD19 Chimeric Antigen Receptor-T cell (CAR19T2 T cell) in children with refractory/relapsed B-cell acute lymphoblastic leukemia/lymphoma.","detailedDescription":"CD19 CAR-T cells treating B-cell hematological malignancies have achieved unprecedented success. In this study, we investigated new third-generation autologous T cells (CAR19T2 T cells) genetically modified with humanized anti-CD19 construct incorporating CD28 and Toll-like receptor 2 (TLR2) costimulatory domains. CAR19T2 T cells will be modified before the infusion to those which could identify 